#!/usr/bin/env python3
"""Standalone repository-native Arb fourth-recenter frame audit v0.9.29."""
from __future__ import annotations

import argparse
import base64
import gzip
import hashlib
import importlib.util
import json
import os
import platform
import subprocess
import sys
import time
from decimal import Decimal, getcontext
from pathlib import Path
from typing import Any

VERSION = "0.9.29"
TITLE = "GEOMETRIC-FLOW FORMAL FOURTH-RECENTER PARAMETRIC ROOT / TANGENT-NORMAL FRAME"
EMBEDDED_V0928_SHA256 = "a3422754f2b7c2359d03187c441a70421b5368bcee0fb61c2598eef674b9727a"
EMBEDDED_V0928_GZIP_B64 = ""
getcontext().prec = 90


def sha256_file(path: Path) -> str:
    h = hashlib.sha256()
    with path.open("rb") as f:
        for block in iter(lambda: f.read(1 << 20), b""):
            h.update(block)
    return h.hexdigest()


def sha256_json(value: Any) -> str:
    return hashlib.sha256(json.dumps(value, sort_keys=True, separators=(",", ":"), allow_nan=False).encode()).hexdigest()


def atomic_json(path: Path, value: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_suffix(path.suffix + ".tmp")
    tmp.write_text(json.dumps(value, indent=2, sort_keys=True, allow_nan=False) + "\n", encoding="utf-8")
    tmp.replace(path)


def materialize(path: Path) -> Path:
    raw = gzip.decompress(base64.b64decode(EMBEDDED_V0928_GZIP_B64))
    if hashlib.sha256(raw).hexdigest() != EMBEDDED_V0928_SHA256:
        raise RuntimeError("embedded v0.9.28 source hash mismatch")
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(raw)
    return path.resolve()


def load_module(path: Path, name: str):
    spec = importlib.util.spec_from_file_location(name, path)
    if spec is None or spec.loader is None:
        raise RuntimeError(f"cannot load {path.name}")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def six(values: Any, label: str) -> list[Decimal]:
    if not isinstance(values, list) or len(values) != 6:
        raise ValueError(f"{label} must have six entries")
    result = [Decimal(str(x)) for x in values]
    if not all(x.is_finite() for x in result):
        raise ValueError(f"{label} contains non-finite entries")
    return result


def parse() -> tuple[argparse.Namespace, list[str]]:
    parser = argparse.ArgumentParser()
    parser.add_argument("--outdir", default="response_fibre_fourth_frame_v0_9_29_results")
    parser.add_argument("--root-radius", default="2e-18")
    # The complete v0.9.28 box rotates to a worst fourth-frame coordinate of
    # about 1.389e-11.  Use a predeclared 1.5e-11 real start domain, still
    # strictly inside the inherited certified 2e-11 complex graph domain.
    parser.add_argument("--new-domain-radius", default="1.5e-11")
    return parser.parse_known_args()


def run(args: argparse.Namespace) -> dict[str, Any]:
    started = time.time()
    out = Path(args.outdir).resolve()
    out.mkdir(parents=True, exist_ok=True)
    embedded = materialize(out / "embedded_sources" / "response_fibre_third_chart_signed_endpoint_v0_9_28_standalone.py")
    v0928 = load_module(embedded, "embedded_geometric_flow_v0928")
    base_out = out / "v0928_formal_base"
    base = v0928.run(argparse.Namespace(outdir=str(base_out)))
    if base.get("all_scientific_gates_pass") is not True or base.get("fourth_recenter_target_ready") is not True:
        raise RuntimeError("embedded v0.9.28 fourth-recenter target did not pass")

    endpoint_cert_path = Path(base["certificate"])
    endpoint_cert = json.loads(endpoint_cert_path.read_text(encoding="utf-8"))
    target = endpoint_cert["terminal_endpoint_box"]
    centers = six(target["center"], "target center")
    radii = six(target["component_radius"], "target radius")
    coordinate = str(endpoint_cert["coordinate_system"])

    drivers = list(base_out.rglob("instrumented_repository_backend_v0_9_25.py"))
    if len(drivers) != 1:
        raise RuntimeError(f"expected one repository-native driver, found {len(drivers)}")
    source_driver = drivers[0]
    v0925_sources = list(base_out.rglob("response_fibre_third_frame_backend_v0_9_25_standalone.py"))
    if len(v0925_sources) != 1:
        raise RuntimeError(f"expected one embedded v0.9.25 source, found {len(v0925_sources)}")
    v0925 = load_module(v0925_sources[0], "embedded_geometric_flow_v0925_for_v0929")

    # Reuse the already exercised Arb frame-producing proof block, but bind it
    # to the fourth target and inject it after the v0.9.26 switch has made the
    # active base/frame the certified third chart.
    fourth_code = v0925.THIRD_FRAME_ARB_CODE.replace("v0925", "v0929").replace("V0925", "V0929")
    fourth_code = fourth_code.replace(
        '"schema":"geometric-flow/third-recentered-frame/v0.9.24"',
        '"schema":"geometric-flow/fourth-recentered-frame/v0.9.29"',
    ).replace(
        '"generator_version":"0.9.25"', '"generator_version":"0.9.29"'
    ).replace(
        '"v0.9.25-third-recentered-intrinsic-tangent"',
        '"v0.9.29-fourth-recentered-intrinsic-tangent"',
    ).replace(
        "third tangent/normal frame and complete endpoint-box overlap only; no third graph, Picard chart, complete child, or global flow",
        "fourth tangent/normal frame and complete endpoint-box overlap only; no fourth graph, Picard chart, complete child, or global flow",
    )
    # v0.9.28 certifies a real six-dimensional endpoint box.  Preserve that
    # real type in the overlap image instead of spuriously adding an equal
    # imaginary radius (which inflates upper_point by sqrt(2)).  The separate
    # complex Krawczyk root box above remains complex and unchanged.
    real_overlap_old = "v0929_phase_delta.append(acb(ball(0,v0929_dr),ball(0,v0929_dr)))"
    real_overlap_new = "v0929_phase_delta.append(acb(ball(0,v0929_dr),arb(0)))"
    if fourth_code.count(real_overlap_old) != 1:
        raise RuntimeError("fourth real-overlap type hook is not unique")
    fourth_code = fourth_code.replace(real_overlap_old, real_overlap_new, 1)
    driver_text = source_driver.read_text(encoding="utf-8")
    # This file is the repository-native wrapper whose ARB_CODE string is
    # injected into the frozen v0.9.3 generator.  Insert the fourth block at
    # the unique end of the already-certified third-centre switch, immediately
    # before the inherited v0.9.8/v0.9.9 report update.  Looking for the later
    # tangent_domain statement here would be wrong because it lives in the
    # generator acquired only when this wrapper executes.
    hook = "    v098_cert.update({"
    if driver_text.count(hook) != 1:
        raise RuntimeError("fourth-frame injection hook is not unique")
    patched_driver = out / "instrumented_repository_backend_v0_9_29.py"
    patched_driver.write_text(driver_text.replace(hook, fourth_code + "\n" + hook, 1), encoding="utf-8")

    third_frame_paths = list(base_out.rglob("third_frame_arb_certificate.json"))
    third_picard_paths = []
    for p in base_out.rglob("intrinsic_picard_microstep_certificate.json"):
        d = json.loads(p.read_text(encoding="utf-8"))
        if d.get("v0922_signed_field_export_coordinate_system") == "v0.9.26-third-recentered-intrinsic-tangent":
            third_picard_paths.append((p, d))
    target_v0923_paths = list(base_out.rglob("third_recenter_target_certificate.json"))
    if len(third_frame_paths) != 1 or len(third_picard_paths) != 1 or len(target_v0923_paths) < 1:
        raise RuntimeError("frozen third-chart proof inputs are not uniquely available")
    third_frame = json.loads(third_frame_paths[0].read_text(encoding="utf-8"))
    third_picard_path, third_picard = third_picard_paths[0]
    target_v0923 = json.loads(target_v0923_paths[0].read_text(encoding="utf-8"))
    third_graph_radius = Decimal(str(third_picard["refined_normal_graph_radius"]))
    endpoint_semantic_sha = sha256_json({
        "coordinate_system": coordinate,
        "center": target["center"],
        "component_radius": target["component_radius"],
        "step_count": endpoint_cert["step_count"],
        "total_certified_time": endpoint_cert["total_certified_time"],
    })
    fourth_cert_path = (out / "fourth_frame_arb_certificate.json").resolve()
    shadow_third_cert = (out / "shadow_third_frame_certificate.json").resolve()
    env = dict(os.environ)
    env.update({
        "V0925_A_C": ",".join(third_frame["third_tangent_target_center"]),
        "V0925_A_RADIUS": ",".join(third_frame["third_tangent_target_component_radius"]),
        "V0925_ROOT_RADIUS": str(args.root_radius),
        "V0925_GRAPH_NORMAL_RADIUS": str(target_v0923["normal_root_enclosure_radius"]),
        "V0925_NEW_DOMAIN_RADIUS": str(args.new_domain_radius),
        "V0925_V0923_SHA256": third_frame["frozen_v0923_source_sha256"],
        "V0925_TARGET_SHA256": third_frame["frozen_target_certificate_sha256"],
        "V0925_TARGET_SEMANTIC_SHA256": third_frame["frozen_target_semantic_sha256"],
        "V0925_COORDINATE_FROM": third_frame["coordinate_system_from"],
        "V0925_CERTIFICATE": str(shadow_third_cert),
        "V0929_A_C": ",".join(str(x) for x in centers),
        "V0929_A_RADIUS": ",".join(str(x) for x in radii),
        "V0929_ROOT_RADIUS": str(args.root_radius),
        "V0929_GRAPH_NORMAL_RADIUS": str(third_graph_radius),
        "V0929_NEW_DOMAIN_RADIUS": str(args.new_domain_radius),
        "V0929_V0923_SHA256": third_frame["frozen_v0923_source_sha256"],
        "V0929_TARGET_SHA256": sha256_file(endpoint_cert_path),
        "V0929_TARGET_SEMANTIC_SHA256": endpoint_semantic_sha,
        "V0929_COORDINATE_FROM": coordinate,
        "V0929_CERTIFICATE": str(fourth_cert_path),
    })
    backend = subprocess.run(
        [sys.executable, str(patched_driver), "--outdir", str(out / "formal_fourth_frame_backend"), "--root-radius", str(args.root_radius), "--no-install"],
        text=True, capture_output=True, env=env,
    )
    (out / "backend_stdout.txt").write_text(backend.stdout, encoding="utf-8")
    (out / "backend_stderr.txt").write_text(backend.stderr, encoding="utf-8")
    if not fourth_cert_path.is_file():
        raise RuntimeError(f"fourth-frame Arb backend exit={backend.returncode}; certificate missing")
    cert = json.loads(fourth_cert_path.read_text(encoding="utf-8"))
    target_max = max(abs(centers[i]) + radii[i] for i in range(6))
    inherited_outer = Decimal(str(third_picard["outer_complex_tangent_radius"]))
    inherited_parametric_root = (
        third_picard.get("gates", {}).get("complex_parametric_fibre_graph") is True
        and target_max < inherited_outer
    )
    gates = {
        "embedded_v0928_hash_exact": sha256_file(embedded) == EMBEDDED_V0928_SHA256,
        "v0928_complete_signed_endpoint_box": base.get("signed_six_component_terminal_endpoint_box_certified") is True,
        "complete_target_box_inside_inherited_complex_graph": inherited_parametric_root,
        "fourth_start_domain_strictly_inside_inherited_complex_domain": Decimal(str(args.new_domain_radius)) < inherited_outer,
        "unique_parametric_normal_root_inherited_over_complete_box": inherited_parametric_root,
        "repository_native_driver_unique": len(drivers) == 1,
        "instrumented_backend_exit_zero": backend.returncode == 0,
        "certificate_schema_exact": cert.get("schema") == "geometric-flow/fourth-recentered-frame/v0.9.29",
        "certificate_bound_to_endpoint_target": cert.get("frozen_target_semantic_sha256") == endpoint_semantic_sha,
        "formal_precision_at_least_192_bits": int(cert.get("precision_bits", 0)) >= 192,
        "unique_fourth_center_normal_root": cert.get("unique_normal_root_certified") is True,
        "fourth_response_full_row_rank": cert.get("full_response_row_rank_certified") is True,
        "fourth_frame_orthogonal_complete": cert.get("frame_orthogonal_complete_certified") is True,
        "fourth_normal_derivative_invertible": cert.get("normal_derivative_invertible_certified") is True,
        "complete_endpoint_box_overlap_in_fourth_frame": cert.get("endpoint_overlap_in_new_frame_certified") is True,
        "all_backend_frame_gates": cert.get("all_backend_gates_pass") is True,
    }
    passed = all(gates.values())
    result = {
        "title": TITLE,
        "version": VERSION,
        "scientific_status": "VALIDATED_FOURTH_RECENTER_PARAMETRIC_ROOT_AND_TANGENT_NORMAL_FRAME_CERTIFIED" if passed else "FOURTH_RECENTER_FRAME_INCONCLUSIVE_FAIL_CLOSED",
        "repository": v0925.REPOSITORY,
        "frozen_commit": v0925.FROZEN_COMMIT,
        "formal_backend": "python-flint/Arb 192-bit",
        "fourth_recenter_target": {"center": [str(x) for x in centers], "component_radius": [str(x) for x in radii], "maximum_absolute_coordinate": str(target_max)},
        "certificate": str(fourth_cert_path),
        "certificate_sha256": sha256_file(fourth_cert_path),
        "certificate_metrics": {k: cert.get(k) for k in ["normal_root_center", "normal_root_radius", "krawczyk_maximum_utilization", "krawczyk_minimum_margin", "response_singular_values_midpoint", "minimum_response_singular_value_lower", "frame_orthogonal_completeness_defect_upper", "normal_identity_defect_upper", "tangent_response_residual_upper"]},
        "gates": gates,
        "all_scientific_gates_pass": passed,
        "unique_parametric_normal_root_over_complete_endpoint_box_certified": inherited_parametric_root,
        "fourth_tangent_normal_frame_certified": passed,
        "fourth_local_picard_chart_certified": False,
        "complete_child_certified": False,
        "global_flow_claimed": False,
        "next_required_step": "construct and certify the fourth complex fibre graph, pullback metric, normalization branch, and Picard microstep",
        "claim_boundary": "fourth-centre normal root, inherited complete-box parametric root, fourth frame, and endpoint-box overlap only; no fourth Picard chart or global flow",
        "elapsed_seconds": time.time() - started,
        "environment": {"python": platform.python_version(), "platform": platform.platform()},
    }
    result["report_sha256_before_self_field"] = sha256_json(result)
    atomic_json(out / "run_summary.json", result)
    return result


def main() -> int:
    args, ignored = parse()
    if ignored:
        print(f"[notice] ignored notebook/kernel arguments: {ignored}")
    try:
        result = run(args)
        print("=" * 112)
        print(f"{TITLE} v{VERSION}")
        print("=" * 112)
        print(json.dumps(result, indent=2, allow_nan=False))
        return 0 if result["all_scientific_gates_pass"] else 2
    except Exception as exc:
        print(json.dumps({"scientific_status": "V0929_FAILED_CLOSED", "error_type": type(exc).__name__, "error": str(exc)}, indent=2))
        return 2


if __name__ == "__main__":
    code = main()
    if "ipykernel" not in sys.modules and "google.colab" not in sys.modules:
        raise SystemExit(code)
